import numpy as npimport pandas as pdimport matplotlib.pyplot as pltclownfish_data = pd.read_excel('/Users/ggraham/Desktop/multiome_poa/Reference/Complete Data Frame (Hormones, Behavior, Size, Gonads) GG.xlsx')#subset data to include the 3 main classessubset_data = clownfish_data[    (clownfish_data['Status']=='M') |    (clownfish_data['Status']=='F')                             ]test_data = clownfish_data[    (clownfish_data['Status']=='D') |                            (clownfish_data['Status']=='E')|                           (clownfish_data['Status']=='NF')]train_data = subset_datatrain_data.columnsplt.scatter(subset_data['mass_final_cm'][subset_data['Status']=='M'],            subset_data['Log_11KT'][subset_data['Status']=='M'],            color = 'blue',            marker = 'o',             label = 'Male')plt.scatter(subset_data['mass_final_cm'][subset_data['Status']=='F'],            subset_data['Log_11KT'][subset_data['Status']=='F'],            color = 'red',            marker = 's',             label = 'Female')plt.scatter(test_data['mass_final_cm'][test_data['Status']=='D'],            test_data['Log_11KT'][test_data['Status']=='D'],            color = 'green',            marker = 'P',             label = 'Dominant')plt.xlabel('Mass (g')plt.ylabel('Log10 11KT')plt.show()"""Ok a linear classifier should be able to differentiate males, females, and dominants using these two dimensionsFor the purposes of the example though I am just going to do M v F and then test on dominants"""class Perceptron:    def __init__(self, eta = 0.01, n_iter=50, random_state=1):        self.eta = eta #eta is learning rate        self.n_iter= n_iter #number of iterations        self.random_state = random_state #random num generator            def fit(self, X, y):        rgen = np.random.RandomState(self.random_state)        self.w_ = rgen.normal(loc = 0.0, scale = 0.01, size=X.shape[1]) # w is weights        self.b_ = np.float64(0.) #b is 1- theta, theta is 'threshold' for perceptron to return 1 like a neuron's threshold potential                self.errors_=[]                for i in range(self.n_iter):            errors = 0            for xi, target in zip(X, y): #zip is similar to cbind in R, so each item is paired, xi is x ith input, target is ylabel which is the correct answer I think                update = self.eta * (target - self.predict(xi))                self.w_ += update * xi                self.b_ += update                errors += int(update != 0.0)            self.errors_.append(errors)        return self    def net_input(self, X):        """Calculate net input"""        return np.dot(X, self.w_) + self.b_        def predict(self, X):        return np.where(self.net_input(X) >= 0.0, 1, 0)    train_data['Log_11KT'][train_data['Status']=='M'].plot.hist(bins = 3)train_data['Log_11KT'][train_data['Status']=='M'].mean()train_data['Log_11KT'][train_data['Status']=='F'].mean()clown_X = train_data[['mass_final_cm','Log_11KT']]# add in missing valuesclown_X['Log_11KT'][9] = train_data['Log_11KT'][train_data['Status']=='M'].mean()clown_X['Log_11KT'][8] = train_data['Log_11KT'][train_data['Status']=='F'].mean()clown_X = clown_X.valuesclown_y = train_data[['Status']]    clown_y = np.where(clown_y == 'F', 1, 0)  clown_perceptron = Perceptron(eta = 0.1, n_iter = 10)    clown_perceptron.fit(clown_X, clown_y)        clown_predictions = clown_perceptron.predict(clown_X)     clown_predictions==   clown_y.flatten()      #100%        plt.plot(range(1, len(clown_perceptron.errors_) + 1),clown_perceptron.errors_, marker='o')plt.xlabel('Epochs')plt.ylabel('Number')plt.show()     #3 epochsdominant_predictions = clown_perceptron.predict(test_data[['mass_final_cm','Log_11KT']])test_data['Perceptron Predictions'] =dominant_predictions       test_data[['Fish', 'Status', 'Perceptron Predictions','mass_final_cm','Log_11KT']]     from matplotlib.colors import ListedColormapdef plot_decision_regions(X, y, classifier, resolution=0.02):# setup marker generator and color map    markers = ('o', 's', '^', 'v', '<')    colors = ('red', 'blue', 'lightgreen', 'gray', 'cyan')    cmap = ListedColormap(colors[:len(np.unique(y))])    # plot the decision surface    x1_min, x1_max = X[:, 0].min() - 1, X[:, 0].max() + 1    x2_min, x2_max = X[:, 1].min() - 1, X[:, 1].max() + 1    xx1, xx2 = np.meshgrid(np.arange(x1_min, x1_max, resolution),    np.arange(x2_min, x2_max, resolution))    lab = classifier.predict(np.array([xx1.ravel(), xx2.ravel()]).T)    lab = lab.reshape(xx1.shape)    plt.contourf(xx1, xx2, lab, alpha=0.3, cmap=cmap)    plt.xlim(xx1.min(), xx1.max())    plt.ylim(xx2.min(), xx2.max())        plot_decision_regions(clown_X, clown_y, clown_perceptron)    plt.xlabel('Mass (g)')plt.ylabel('Log 11KT')plt.scatter(subset_data['mass_final_cm'][subset_data['Status']=='M'],            subset_data['Log_11KT'][subset_data['Status']=='M'],            color = 'red',            marker = 'o',             label = 'Male')plt.scatter(subset_data['mass_final_cm'][subset_data['Status']=='F'],            subset_data['Log_11KT'][subset_data['Status']=='F'],            color = 'blue',            marker = 's',             label = 'Female')plt.scatter(test_data['mass_final_cm'][test_data['Status']=='D'],            test_data['Log_11KT'][test_data['Status']=='D'],            color = 'green',            marker = 'P',             label = 'Dominant')plt.scatter(test_data['mass_final_cm'][test_data['Status']=='E'],            test_data['Log_11KT'][test_data['Status']=='E'],            color = 'pink',            marker = 'P',             label = 'Expanded')plt.scatter(test_data['mass_final_cm'][test_data['Status']=='NF'],            test_data['Log_11KT'][test_data['Status']=='NF'],            color = 'brown',            marker = 'P',             label = 'New Female')plt.legend(loc='upper right')plt.show()        